const payload = $("[CRUD] Agend.AI").first().json.body;
const nome = payload.nome;
const partesNome = nome.trim().split(" ");
const timezone = payload.timezone;

let nome_agenda = "";
let prefixo = "";

const response = await this.helpers.httpRequest({
  method: "GET",
  url: `https://api.genderize.io?name=${partesNome[0]}`,
  json: true
});

if(response.probability > 0.9) {
  prefixo = (response.gender === "male") ? "Dr." : "Dra."
}
else {
  prefixo = "Dr(a)."
}

if(partesNome.length > 2) {
  nome_agenda = `${prefixo} ${partesNome[0]} ${partesNome[1][0].toUpperCase()} ${partesNome.at(-1) }`;
}
else {
  nome_agenda = `${prefixo} ${nome}`;
}

return [{
  json: {
    prefixo: prefixo,
    nome_completo: nome,
    nome_agenda: nome_agenda,
    timezone: timezone,
  }
}];

const payload = $("[CRUD] Agend.AI").first().json.body;

const dadosEvento = payload.evento;
const dadosProfissional = payload.profissional;
const dadosCliente = payload.cliente;

const titulo = `${dadosCliente.nome} - ${dadosProfissional.procedimento}`;
const descricao = dadosEvento.motivo_contato;
const event_id = dadosEvento.id_evento_calendar;

return [{
  json: {
    id_agendamento: dadosEvento.uuid,
    id_calendar: dadosProfissional.id_calendar,
    event_id: event_id,
    titulo: titulo,
    descricao: descricao,
    inicio: dadosEvento.hora_inicio,
    fim: dadosEvento.hora_fim
  }
}];

const data = $("[GET] Consultar eventos by Agenda").all();
const profissionalUuid = $('[SET] Dados Busca Agenda').first().json.profissional_uuid;
const events = [];

if(data.isEmpty) {
  for (const item of data) {
    const event = item.json;
    const id = event.id;
    const cliente = event.summary.split(" - ")[0];
    const procedimento = event.summary.split(" - ")[1];
    const inicio = event.start?.dateTime; // Vem no formato 2026-08-07T18:00:00Z, com o timezone America/Sao_Paulo. converter para -03:00
    const fim = event.end?.dateTime;

    events.push({
      id: id,
      title: cliente.trim() || null,
      inicio: inicio,
      fim: fim,
      extendedProps: {
        patient: cliente.trim() || null,
        procedure: procedimento || null,
        doctorUuid: profissionalUuid
      }
    })
  }
}


return [
  {
    json: {
      events
    },
  },
];

