const entrada = $("[SET] Dados Busca Disponibilidade").first().json;
const itensGoogle = $("[GET] Eventos próximos Dias").all();

const timezone = entrada.timezone ?? "America/Sao_Paulo";
const quantidade = entrada.quantidade_alternativas ?? 3;
const diasBusca = entrada.dias_busca ?? 7;
const duracaoMinutos = entrada.duracao_sessao_minutos ?? 60;

const eventosGoogle = itensGoogle.flatMap((item) => {
  if (Array.isArray(item.json.items)) {
    return item.json.items;
  }

  return Object.keys(item.json).length
    ? [item.json]
    : [];
});

function obterDataEvento(evento, propriedade) {
  const valor = evento[propriedade];

  if (typeof valor === "string") {
    return valor;
  }

  return valor?.dateTime ?? valor?.date ?? null;
}

const ocupados = eventosGoogle
  .filter((evento) => evento.status !== "cancelled")
  .map((evento) => {
    const inicio = obterDataEvento(evento, "start");
    const fim = obterDataEvento(evento, "end");

    return {
      inicio: inicio
        ? DateTime.fromISO(inicio, { zone: timezone }).toMillis()
        : NaN,

      fim: fim
        ? DateTime.fromISO(fim, { zone: timezone }).toMillis()
        : NaN,
    };
  })
  .filter(
    (evento) =>
      Number.isFinite(evento.inicio) &&
      Number.isFinite(evento.fim) &&
      evento.fim > evento.inicio,
  );

function extrairHorario(valor) {
  /*
   * Aceita tanto:
   *
   * "08:00"
   *
   * quanto:
   *
   * "2026-08-12T08:00:00-03:00"
   */
  const resultado = valor.match(
    /(?:T)?(\d{2}):(\d{2})(?::(\d{2}))?/,
  );

  if (!resultado) {
    throw new Error(`Horário inválido: ${valor}`);
  }

  return {
    hora: Number(resultado[1]),
    minuto: Number(resultado[2]),
    segundo: Number(resultado[3] ?? 0),
  };
}

const regrasPorDia = new Map();

for (const janela of entrada.janelas_atendimento ?? []) {
  const diaSemana = Number(
    janela.dia_semana,
  );

  regrasPorDia.set(diaSemana, {
    inicio: extrairHorario(janela.inicio),
    fim: extrairHorario(janela.fim),
  });
}

function possuiConflito(inicio, fim) {
  const inicioMillis = inicio.toMillis();
  const fimMillis = fim.toMillis();

  return ocupados.some(
    (ocupado) =>
      inicioMillis < ocupado.fim &&
      fimMillis > ocupado.inicio,
  );
}

const inicioBusca = DateTime
  .fromISO(entrada.periodo_solicitado.fim, {
    setZone: true,
  })
  .setZone(timezone);

if (!inicioBusca.isValid) {
  throw new Error(
    "periodo_solicitado.fim é inválido.",
  );
}

const fimBusca = inicioBusca.plus({
  days: diasBusca,
});

const alternativas = [];

let diaAtual = inicioBusca.startOf("day");

while (
  diaAtual < fimBusca &&
  alternativas.length < quantidade
) {
  const regra = regrasPorDia.get(diaAtual.weekday);

  /*
   * Se não existir regra para o dia, a clínica está
   * fechada. Por exemplo, domingo.
   */
  if (regra) {
    const abertura = diaAtual.set({
      hour: regra.inicio.hora,
      minute: regra.inicio.minuto,
      second: regra.inicio.segundo,
      millisecond: 0,
    });

    const fechamento = diaAtual.set({
      hour: regra.fim.hora,
      minute: regra.fim.minuto,
      second: regra.fim.segundo,
      millisecond: 0,
    });

    /*
     * No primeiro dia, começa no fim do período recusado.
     * Nos próximos dias, começa na abertura da clínica.
     */
    let candidato =
      inicioBusca > abertura
        ? inicioBusca
        : abertura;

    while (
      candidato.plus({
        minutes: duracaoMinutos,
      }) <= fechamento &&
      candidato < fimBusca &&
      alternativas.length < quantidade
    ) {
      const candidatoFim = candidato.plus({
        minutes: duracaoMinutos,
      });

      if (!possuiConflito(candidato, candidatoFim)) {
        alternativas.push({
          inicio: candidato.toISO(),
          fim: candidatoFim.toISO(),
        });
      }

      /*
       * Para manter simples, a duração também funciona
       * como intervalo entre possíveis horários.
       */
      candidato = candidato.plus({
        minutes: duracaoMinutos,
      });
    }
  }

  diaAtual = diaAtual.plus({
    days: 1,
  });
}

return [
  {
    json: {
      sucesso: true,
      disponivel: false,
      codigo: "horario_indisponivel",
      timezone,
      profissional_uuid:
        entrada.profissional_uuid,
      periodo_solicitado:
        entrada.periodo_solicitado,
      alternativas,
      busca_esgotada:
        alternativas.length < quantidade,
    },
  },
];

